UPDATE tools SET faq = $x$[{"q": "What is OpenAI Codex?", "a": "OpenAI Codex is OpenAI's coding agent. It takes tasks such as fixing bugs, refactoring, adding features and writing tests, works through your repository and returns changes for review. It runs in the ChatGPT apps, the Codex CLI, an IDE extension and Codex cloud, and can also review pull requests automatically."}, {"q": "Is OpenAI Codex free?", "a": "Partly. The ChatGPT Free plan and Go ($8 a month) include lightweight Codex use in the desktop app with the GPT-6 Luna model, subject to rollout. Full Codex on the web, CLI, IDE extension and iOS starts with ChatGPT Plus at $20 a month. Pro costs $100, $200 or $500 a month, and Business is $20 per user per month billed annually or $25 billed monthly."}, {"q": "Which models does Codex use?", "a": "As of October 2026, OpenAI lists five models on the Codex pricing page: GPT-6 Astra, GPT-6.1 Sol, GPT-6.1 Terra, GPT-6 Sol and GPT-6 Luna, with Terra added on October 26, 2026. Plus and Business users get access to all five; Free and Go only get GPT-6 Luna in the desktop app."}, {"q": "What are the Codex usage limits?", "a": "On Plus and Business, Codex usage is measured per five-hour window. OpenAI estimates about 5 to 45 local messages per five hours with GPT-6 Astra, 15 to 160 with GPT-6.1 Sol, 35 to 285 with GPT-6.1 Terra, 15 to 150 with GPT-6 Sol, and 350 to 3,000 with GPT-6 Luna. Pro currently has no five-hour limit, and OpenAI doubled its Work and Codex allowances on October 29, 2026. Plus, Pro and Business users can also buy extra credits."}]$x$::jsonb
 WHERE slug = 'openai-codex' AND lang = 'en';

