 WHERE slug = 'github-copilot' AND lang = 'de';

UPDATE tools SET cons = ARRAY[$x$Nutzungsbasierte AI-Credits-Abrechnung bedeutet, dass die Kosten den Grundpreis des Abonnements übersteigen können, sobald zusätzliche Credits über das inkludierte Guthaben hinaus gekauft werden, was die monatlichen Ausgaben für intensive Nutzer schwerer vorhersehbar macht$x$, $x$Die Delegation an Drittanbieter-Agenten und die größten Credit-Kontingente sind den teureren Stufen Pro+ und Max vorbehalten$x$, $x$Die kostenlose Stufe ist auf etwa 2.000 Inline-Vorschläge begrenzt, mit eingeschränktem Chat- und Agentenzugang und ohne Code-Review oder Cloud-Agenten$x$, $x$Die neue Enterprise-Lizenzierung (Copilot gebündelt mit GitHub Enterprise Cloud auf Basis eines gemeinsamen Nutzungsbudgets oder Copilot Standalone für 10 $/Nutzer/Monat) wird noch schrittweise im Self-Service eingeführt, sodass Verfügbarkeit und genaue Konditionen je nach Organisation variieren können$x$, $x$Flex-Credit-Kontingente sind ohne Mehrkosten enthalten, aber GitHub weist darauf hin, dass sich der Umfang im Laufe der Zeit ändern kann, sodass die gesamte inkludierte Nutzung nicht garantiert konstant bleibt$x$]::text[]
 WHERE slug = 'github-copilot' AND lang = 'de';

UPDATE tools SET choose_if = $x$["🔧 Sie entwickeln bereits auf GitHub und möchten den Assistenten direkt in diesen Workflow eingebettet haben", "🤖 Sie wünschen ein agentisches Coding-Tool, nicht nur zeilenweises Autocomplete", "🔀 Sie möchten für unterschiedliche Aufgaben zwischen Modellen verschiedener Anbieter wählen", "🎓 Sie sind eine verifizierte Lehrkraft oder Maintainer eines populären Open-Source-Projekts und wünschen kostenlosen Pro-Zugang", "💰 Sie benötigen Admin-Budgets und Ausgabenobergrenzen, um die KI-Ausgaben des Teams zu kontrollieren"]$x$::jsonb
