UPDATE tools SET cons = ARRAY[$x$Биллинг на основе использования AI Credits означает, что расходы могут превысить базовую цену подписки после покупки дополнительных кредитов сверх включённого лимита, что усложняет прогнозирование ежемесячных затрат для активных пользователей$x$, $x$Делегирование сторонним агентам и самые большие лимиты кредитов доступны только на более дорогих тарифах Pro+ и Max$x$, $x$Бесплатный тариф ограничен примерно 2000 встроенными подсказками с ограниченным доступом к чату и агенту и без код-ревью и облачных агентов$x$, $x$Новая система корпоративного лицензирования (Copilot в составе GitHub Enterprise Cloud с общим бюджетом использования или Copilot Standalone за $10 на пользователя в месяц) всё ещё внедряется поэтапно для аккаунтов с самостоятельной регистрацией, поэтому доступность и точные условия могут различаться в зависимости от организации$x$, $x$Гибкие (flex) лимиты кредитов включены без дополнительной платы, но GitHub сообщает, что их объём может со временем меняться, поэтому общий объём включённого использования не гарантированно останется неизменным$x$]::text[]
 WHERE slug = 'github-copilot' AND lang = 'ru';

UPDATE tools SET choose_if = $x$["🐙 Вы уже разрабатываете на GitHub и хотите, чтобы ассистент был встроен в этот рабочий процесс", "🤖 Вы хотите агентный инструмент для кодинга, а не просто построчное автодополнение", "🔀 Вы хотите выбирать модели от разных вендоров под разные задачи", "🎓 Вы верифицированный преподаватель или мейнтейнер популярного open source проекта и хотите получить бесплатный доступ к Pro", "💰 Вам нужны бюджет администратора и лимиты расходов для контроля затрат команды на ИИ"]$x$::jsonb
