 WHERE slug = 'gemini' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "On Google Workspace tasks, Gemini's deep integration with Gmail, Docs and Sheets makes it the more convenient choice. General capability comparisons with other assistants shift too often to declare a lasting winner. Gemini is the strongest fit for people already inside Google's ecosystem, while other assistants may appeal more for general use depending on their own feature sets.", "q": "Is Gemini better than ChatGPT?"}, {"a": "There is a free plan, but it runs the Flash-Lite model only. Paid plans unlock more: Google AI Plus is $4.99/month with the Flash model, Google AI Pro is $19.99/month and includes the flagship Gemini 4 Argon model, and Google AI Ultra is $99.99/month or $199.99/month for higher usage limits.", "q": "Is Gemini free?"}, {"a": "Yes. Gemini includes native image generation through the Nano Banana 2.1 model, released October 2026, alongside its chat and coding capabilities.", "q": "Can Gemini generate images?"}, {"a": "Bard was Google's original AI chatbot, rebranded as Gemini in February 2024. They are the same product — if you used Bard, you're now using Gemini. The rebrand accompanied a significant upgrade in model capabilities.", "q": "What is the difference between Gemini and Google Bard?"}]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'en';

