UPDATE tools SET faq = $x$[{"a": "En tareas de Google Workspace, la integración profunda de Gemini con Gmail, Docs y Sheets lo convierte en la opción más conveniente. Las comparaciones generales de capacidad con otros asistentes cambian con demasiada frecuencia como para declarar un ganador duradero. Gemini es la opción más adecuada para personas ya inmersas en el ecosistema de Google, mientras que otros asistentes pueden resultar más atractivos para uso general según sus propias características.", "q": "¿Es Gemini mejor que ChatGPT?"}, {"a": "Existe un plan gratuito, pero solo ejecuta el modelo Flash-Lite. Los planes de pago desbloquean más funciones: Google AI Plus cuesta $4.99/mes con el modelo Flash, Google AI Pro cuesta $19.99/mes e incluye el modelo insignia Gemini 4 Argon, y Google AI Ultra cuesta $99.99/mes o $199.99/mes para límites de uso más altos.", "q": "¿Es gratis Gemini?"}, {"a": "Sí. Gemini incluye generación de imágenes nativa a través del modelo Nano Banana 2.1, lanzado en octubre de 2026, junto con sus capacidades de chat y programación.", "q": "¿Puede Gemini generar imágenes?"}, {"a": "Bard fue el chatbot de IA original de Google, renombrado como Gemini en febrero de 2024. Son el mismo producto: si usabas Bard, ahora estás usando Gemini. El cambio de nombre vino acompañado de una mejora significativa en las capacidades del modelo.", "q": "¿Cuál es la diferencia entre Gemini y Google Bard?"}]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'es';

