UPDATE tools SET faq = $x$[{"a": "Bei Google-Workspace-Aufgaben macht Geminis tiefe Integration mit Gmail, Docs und Sheets es zur bequemeren Wahl. Allgemeine Leistungsvergleiche mit anderen Assistenten ändern sich zu häufig, um einen dauerhaften Sieger zu bestimmen. Gemini passt am besten zu Menschen, die bereits in Googles Ökosystem arbeiten, während andere Assistenten je nach ihren eigenen Funktionen für die allgemeine Nutzung attraktiver sein können.", "q": "Ist Gemini besser als ChatGPT?"}, {"a": "Es gibt einen kostenlosen Plan, der jedoch nur das Flash-Lite-Modell nutzt. Kostenpflichtige Pläne bieten mehr: Google AI Plus kostet 4,99 $/Monat mit dem Flash-Modell, Google AI Pro kostet 19,99 $/Monat und enthält das Flaggschiffmodell Gemini 4 Argon, und Google AI Ultra kostet 99,99 $/Monat oder 199,99 $/Monat für höhere Nutzungslimits.", "q": "Ist Gemini kostenlos?"}, {"a": "Ja. Gemini bietet native Bilderzeugung über das Modell Nano Banana 2.1, veröffentlicht im Oktober 2026, zusätzlich zu seinen Chat- und Programmierfunktionen.", "q": "Kann Gemini Bilder erzeugen?"}, {"a": "Bard war Googles ursprünglicher KI-Chatbot, der im Februar 2024 in Gemini umbenannt wurde. Es handelt sich um dasselbe Produkt — wer Bard genutzt hat, verwendet jetzt Gemini. Die Umbenennung ging mit einer deutlichen Verbesserung der Modellfähigkeiten einher.", "q": "Was ist der Unterschied zwischen Gemini und Google Bard?"}]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'de';

