UPDATE tools SET faq = $x$[{"a": "В задачах, связанных с Google Workspace, глубокая интеграция Gemini с Gmail, Docs и Sheets делает его более удобным выбором. Общие сравнения возможностей с другими ассистентами меняются слишком часто, чтобы объявить постоянного победителя. Gemini лучше всего подходит людям, уже находящимся в экосистеме Google, в то время как другие ассистенты могут быть привлекательнее для общего использования в зависимости от их собственных функций.", "q": "Gemini лучше ChatGPT?"}, {"a": "Есть бесплатный план, но он работает только на модели Flash-Lite. Платные тарифы открывают больше возможностей: Google AI Plus стоит $4,99 в месяц и включает модель Flash, Google AI Pro стоит $19,99 в месяц и включает флагманскую модель Gemini 4 Argon, а Google AI Ultra стоит $99,99 или $199,99 в месяц за более высокие лимиты использования.", "q": "Gemini бесплатен?"}, {"a": "Да. Gemini включает встроенную генерацию изображений через модель Nano Banana 2.1, выпущенную в октябре 2026 года, наряду с возможностями чата и программирования.", "q": "Может ли Gemini генерировать изображения?"}, {"a": "Bard был первоначальным ИИ-чат-ботом Google, переименованным в Gemini в феврале 2024 года. Это один и тот же продукт — если вы пользовались Bard, теперь вы используете Gemini. Ребрендинг сопровождался значительным улучшением возможностей модели.", "q": "В чём разница между Gemini и Google Bard?"}]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'ru';

