 WHERE slug = 'gemini' AND lang = 'he';

UPDATE tools SET description_long = $x$Gemini היא משפחת מודלי הבינה המלאכותית של Google והעוזר הצרכני הבנוי עליהם, הזמין באינטרנט, באפליקציה לנייד ובתוך אפליקציות Workspace כמו Gmail, Docs ו-Sheets. הוא מטפל בשיחה, ניתוח מסמכים, יצירת תמונות, תכנות ואינטראקציה קולית חיה.

נכון לסוף אוקטובר 2026, מודל הדגל הזמין לציבור הוא Gemini 4 Argon, שהוכרז ב-30 בספטמבר 2026 עבור מגיני סייבר מאושרים והפך לזמין באופן כללי ב-13 באוקטובר 2026. ב-28 באוקטובר 2026 הודיעה Google על Gemini 4 Carbon כמודל החזק ביותר שלה עד כה, המוביל את מדד Artificial Analysis Intelligence Index, אך Carbon מוגבל בתחילה לקבוצה קטנה של מגיני סייבר ושותפי Fairwind Program, ללא תאריך קבוע עדיין לשחרור למפתחים, עסקים או צרכנים. מודל ה-Flash החדש ביותר הוא Gemini 3.8 Flash, שהגיע לזמינות כללית ב-2 בספטמבר 2026 וקדם ל-Argon, ומודל התמונות הנוכחי הוא Nano Banana 2.1, שיצא ב-6 באוקטובר 2026. המודלים הישנים יותר Gemini 3.7 Flash ו-3.5 Flash הוצאו משימוש מה-API ב-8 באוקטובר 2026.

Gemini 4 Argon מקבל קלט טקסט, תמונות, וידאו, אודיו וקבצי PDF ומפיק פלט טקסט, עם מגבלה משולבת של קלט ופלט של כ-1 מיליון טוקנים. הוא זמין באפליקציית Gemini ובמצב AI Mode בחיפוש Google עבור מנויי AI Pro ו-AI Ultra. אפליקציית Gemini גם הוסיפה מצב משימות וחיבורים ליותר מ-40 אפליקציות חיצוניות ב-13 באוקטובר 2026. ב-AI Studio וב-Antigravity, Argon מוצע למנויי AI Ultra, בעוד שמשתמשי AI Pro זקוקים למפתח API בתשלום נפרד כדי להשתמש בו שם.

התמחור באפליקציית Gemini (ארה"ב, חודשי) הוא כדלקמן: Free ב-0 דולר, הכולל את מודל Flash-Lite; Google AI Plus ב-4.99 דולר, הכולל את מודל Flash; Google AI Pro ב-19.99 דולר, הכולל את Gemini 4 Argon לצד מודלי Pro ו-Flash; ו-Google AI Ultra ב-99.99 דולר עבור פי 5 ממגבלות השימוש של AI Pro או ב-199.99 דולר עבור פי 20. Gemini 4 Argon אינו זמין במסלולי Free או Plus. דרך ה-API, Argon מחויב ב-2 דולר למיליון טוקני קלט ו-10 דולר למיליון טוקני פלט עד ה-30 בנובמבר 2026, ועולה ל-4 דולר ו-20 דולר לאחר תאריך זה; קלט שמור במטמון מוזל, עיבוד batch ו-flex הוא במחצית המחיר, ואין מסלול API חינמי עבור Argon.

המגבלות כוללות שמות מבלבלים של מודלים ומסלולים (Flash, Pro, Argon, Carbon, Plus, Ultra), העובדה שמודל הדגל Argon נעול מאחורי מנויי Pro או Ultra, הצורך במפתח API בתשלום נפרד אם משתמשי AI Pro רוצים את Argon ב-AI Studio או ב-Antigravity, והעלאת מחירי API מתוכננת בסוף נובמבר 2026.

Gemini מתאים לאנשים הנמצאים כבר בתוך מערכת האקולוגית של Google Workspace, למי שרוצים צ'אט ויצירת תמונות במקום אחד, ולמפתחים המעוניינים בגישה בתשלום לפי טוקן למודל הדגל הנוכחי הזמין לציבור של Google.$x$
 WHERE slug = 'gemini' AND lang = 'he';

