UPDATE tools SET faq = $x$[{"a": "במשימות הקשורות ל-Google Workspace, השילוב העמוק של Gemini עם Gmail, Docs ו-Sheets הופך אותו לבחירה הנוחה יותר. השוואות יכולת כלליות עם עוזרים אחרים משתנות לעיתים קרובות מכדי להכריז על מנצח קבוע. Gemini מתאים ביותר לאנשים הנמצאים כבר בתוך מערכת האקולוגית של Google, בעוד שעוזרים אחרים עשויים למשוך יותר לשימוש כללי בהתאם לתכונות שלהם עצמם.", "q": "האם Gemini טוב יותר מ-ChatGPT?"}, {"a": "קיים מסלול חינמי, אך הוא מפעיל רק את מודל Flash-Lite. מסלולים בתשלום פותחים יותר: Google AI Plus ב-4.99 דולר לחודש עם מודל Flash, Google AI Pro ב-19.99 דולר לחודש הכולל את מודל הדגל Gemini 4 Argon, ו-Google AI Ultra ב-99.99 דולר או 199.99 דולר לחודש עבור מגבלות שימוש גבוהות יותר.", "q": "האם Gemini חינמי?"}, {"a": "כן. Gemini כולל יצירת תמונות מובנית באמצעות מודל Nano Banana 2.1, שיצא באוקטובר 2026, לצד יכולות הצ'אט והתכנות שלו.", "q": "האם Gemini יכול ליצור תמונות?"}, {"a": "Bard היה הצ'אטבוט המקורי מבוסס הבינה המלאכותית של Google, שמותג מחדש כ-Gemini בפברואר 2024. מדובר באותו מוצר — אם השתמשתם ב-Bard, אתם משתמשים כעת ב-Gemini. המיתוג מחדש לווה בשדרוג משמעותי ביכולות המודל.", "q": "מה ההבדל בין Gemini ל-Google Bard?"}]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'he';

