UPDATE tools SET choose_if = $x$["📧 Vous vivez dans Gmail, Docs et Google Workspace et voulez une IA intégrée", "🎨 Vous voulez un chat performant associé à une génération d'images native dans un seul outil", "💻 Vous êtes développeur et souhaitez un accès facturé au token au modèle phare de Google", "🆓 Vous voulez un assistant gratuit avant de vous engager dans une formule payante", "🔍 Vous avez besoin du mode IA dans la recherche en plus d'un abonnement Pro ou Ultra"]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"a": "Sur les tâches liées à Google Workspace, l'intégration poussée de Gemini avec Gmail, Docs et Sheets en fait le choix le plus pratique. Les comparaisons générales de capacités avec d'autres assistants évoluent trop souvent pour désigner un gagnant durable. Gemini convient le mieux aux personnes déjà intégrées à l'écosystème Google, tandis que d'autres assistants peuvent séduire davantage pour un usage général selon leurs propres fonctionnalités.", "q": "Gemini est-il meilleur que ChatGPT ?"}, {"a": "Il existe une formule gratuite, mais elle ne fait tourner que le modèle Flash-Lite. Les formules payantes débloquent davantage : Google AI Plus à 4,99 $/mois avec le modèle Flash, Google AI Pro à 19,99 $/mois incluant le modèle phare Gemini 4 Argon, et Google AI Ultra à 99,99 $/mois ou 199,99 $/mois pour des limites d'usage supérieures.", "q": "Gemini est-il gratuit ?"}, {"a": "Oui. Gemini propose une génération d'images native grâce au modèle Nano Banana 2.1, sorti en octobre 2026, en plus de ses capacités de chat et de code.", "q": "Gemini peut-il générer des images ?"}, {"a": "Bard était le chatbot IA original de Google, rebaptisé Gemini en février 2024. Il s'agit du même produit : si vous utilisiez Bard, vous utilisez désormais Gemini. Ce changement de nom s'est accompagné d'une amélioration significative des capacités du modèle.", "q": "Quelle est la différence entre Gemini et Google Bard ?"}]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'fr';

