UPDATE tools SET faq = $x$[{"a": "Canva has a Free plan with a limited AI allowance shared across its Standard, Premium, and Ultra AI tools. Paid Pro (US$120/year for one person) and Business (US$210/year per person) plans unlock more AI tools such as Dream Lab image generation (powered by Canva Craft) and Magic Write, plus an optional monthly AI Pass add-on for extra AI usage; Enterprise is custom-priced. Pricing is localized by region.", "q": "Is Canva AI free?"}, {"a": "Figma AI (launched 2024) includes AI-generated layers and designs from text prompts, AI rename for layers, first draft generation, and prototype generation. It's built into Figma and available to all paid plan users.", "q": "What AI features does Figma have?"}, {"a": "No. Canva and Figma serve different purposes. Canva is for creating marketing content and presentations. Figma is for designing UI/UX interfaces and product prototypes. Designers use Figma; content creators use Canva.", "q": "Can Canva replace Figma?"}, {"a": "Canva is significantly easier for beginners — it's designed for non-designers with drag-and-drop simplicity. Figma has a steeper learning curve and is designed for professional designers. For quick graphics, start with Canva.", "q": "Which is better for beginners — Canva or Figma?"}]$x$::jsonb
 WHERE slug = 'canva-ai' AND lang = 'en';

