UPDATE tools SET faq = $x$[{"a": "Canva propose un forfait Gratuit avec un quota d'IA limité partagé entre ses outils IA Standard, Premium et Ultra. Les forfaits payants Pro (120 USD/an pour une personne) et Business (210 USD/an par personne) débloquent davantage d'outils IA comme la génération d'images Dream Lab (propulsée par Canva Craft) et Magic Write, ainsi qu'un module complémentaire mensuel optionnel AI Pass pour une utilisation d'IA supplémentaire ; Enterprise est au prix personnalisé. Les tarifs sont adaptés selon les régions.", "q": "Canva AI est-il gratuit ?"}, {"a": "Figma AI (lancé en 2024) propose des calques et designs générés par IA à partir de requêtes textuelles, le renommage automatique des calques par IA, la génération de premières ébauches et la génération de prototypes. Il est intégré à Figma et accessible à tous les utilisateurs des forfaits payants.", "q": "Quelles fonctionnalités IA propose Figma ?"}, {"a": "Non. Canva et Figma répondent à des besoins différents. Canva sert à créer du contenu marketing et des présentations. Figma sert à concevoir des interfaces UI/UX et des prototypes de produits. Les designers utilisent Figma ; les créateurs de contenu utilisent Canva.", "q": "Canva peut-il remplacer Figma ?"}, {"a": "Canva est nettement plus facile pour les débutants : il est conçu pour les non-designers avec une simplicité de type glisser-déposer. Figma a une courbe d'apprentissage plus raide et est conçu pour les designers professionnels. Pour des graphismes rapides, commencez par Canva.", "q": "Quel est le meilleur choix pour les débutants — Canva ou Figma ?"}]$x$::jsonb
 WHERE slug = 'canva-ai' AND lang = 'fr';

