UPDATE tools SET faq = $x$[{"a": "O Canva tem um plano Free com uma cota de IA limitada compartilhada entre suas ferramentas de IA Standard, Premium e Ultra. Os planos pagos Pro (US$120/ano para uma pessoa) e Business (US$210/ano por pessoa) desbloqueiam mais ferramentas de IA, como a geração de imagens do Dream Lab (alimentada pelo Canva Craft) e o Magic Write, além de um complemento mensal opcional AI Pass para uso adicional de IA; o Enterprise tem preço personalizado. Os preços são localizados por região.", "q": "O Canva AI é gratuito?"}, {"a": "O Figma AI (lançado em 2024) inclui camadas e designs gerados por IA a partir de prompts de texto, renomeação automática de camadas por IA, geração de primeiros rascunhos e geração de protótipos. Está integrado ao Figma e disponível para todos os usuários de planos pagos.", "q": "Quais recursos de IA o Figma tem?"}, {"a": "Não. Canva e Figma atendem a propósitos diferentes. O Canva é para criar conteúdo de marketing e apresentações. O Figma é para projetar interfaces de UI/UX e protótipos de produtos. Designers usam o Figma; criadores de conteúdo usam o Canva.", "q": "O Canva pode substituir o Figma?"}, {"a": "O Canva é significativamente mais fácil para iniciantes — foi projetado para não designers, com simplicidade de arrastar e soltar. O Figma tem uma curva de aprendizado mais acentuada e é voltado para designers profissionais. Para gráficos rápidos, comece com o Canva.", "q": "Qual é melhor para iniciantes — Canva ou Figma?"}]$x$::jsonb
 WHERE slug = 'canva-ai' AND lang = 'pt';

