UPDATE tools SET faq = $x$[{"q": "Qual é a diferença entre Make e n8n?", "a": "Make é uma plataforma de automação visual baseada em nuvem projetada para usuários não técnicos, com mais de 1.500 conectores. n8n é uma ferramenta de automação de código aberto que pode ser auto-hospedada, oferecendo mais flexibilidade técnica e controle via código. Make é mais fácil de usar; n8n é mais poderosa para desenvolvedores."}, {"q": "A n8n é gratuita?", "a": "A n8n é gratuita para auto-hospedagem por meio da Community Edition de código aberto, com execuções ilimitadas e todas as integrações. A versão em nuvem não tem plano gratuito contínuo, apenas um teste gratuito limitado (1.000 execuções, sem necessidade de cartão de crédito). Os planos pagos de nuvem (Starter, Pro, Business) são cobrados anualmente em euros, e os preços do Enterprise são personalizados. A auto-hospedagem exige conhecimento técnico para configuração e manutenção."}]$x$::jsonb
