UPDATE tools SET faq = $x$[{"a": "Mistral Le Chat тепер називається Vibe. Це споживацький AI-асистент від Mistral AI, доступний на chat.mistral.ai, що працює на власних моделях Mistral, наразі побудованих навколо Mistral Medium 3.5. Mistral — французька AI-компанія, що наголошує на європейському суверенітеті даних і розробці моделей з відкритими вагами.", "q": "Що таке Mistral Le Chat?"}, {"a": "Продукт тепер називається Vibe. Він має безкоштовний план з обмеженою кількістю повідомлень, веб-пошуків, кодових сесій, генерацією зображень і $10/місяць у кредитах API. План Pro коштує $14,99/місяць за більшу кількість повідомлень, цілодобове кодування, генерацію зображень та включені кредити API.", "q": "Чи є Le Chat безкоштовним?"}, {"a": "Mistral випускає кілька моделей з відкритими вагами, включно з Mistral Large, Medium 3.5, Small і Ministral, за відкритими ліцензіями, такими як Apache 2.0 або модифікована ліцензія MIT, які розробники можуть завантажувати та запускати самостійно. Vibe — це розміщений споживацький продукт Mistral, побудований на основі цих моделей.", "q": "Чи є моделі Mistral відкритим кодом?"}]$x$::jsonb
