UPDATE tools SET faq = $x$[{"a": "Mistral Le Chat s'appelle désormais Vibe. C'est l'assistant IA grand public de Mistral AI, disponible sur chat.mistral.ai, qui fonctionne sur les propres modèles de Mistral, actuellement construit autour de Mistral Medium 3.5. Mistral est une entreprise française d'IA qui met l'accent sur la souveraineté européenne des données et le développement de modèles à poids ouverts.", "q": "Qu'est-ce que Mistral Le Chat ?"}, {"a": "Le produit s'appelle désormais Vibe. Il dispose d'un plan gratuit avec un nombre limité de messages, de recherches web, de sessions de codage, de génération d'images et de 10 $/mois de crédits API. Le plan Pro coûte 14,99 $/mois pour davantage de messages, le codage toute la journée, la génération d'images et des crédits API inclus.", "q": "Le Chat est-il gratuit ?"}, {"a": "Mistral publie plusieurs modèles avec des poids ouverts, notamment Mistral Large, Medium 3.5, Small et Ministral, sous des licences ouvertes telles qu'Apache 2.0 ou une licence MIT modifiée, que les développeurs peuvent télécharger et exécuter eux-mêmes. Vibe est le produit grand public hébergé par Mistral, construit sur la base de ces modèles.", "q": "Les modèles de Mistral sont-ils open source ?"}]$x$::jsonb
 WHERE slug = 'mistral-le-chat' AND lang = 'fr';

