UPDATE tools SET faq = $x$[{"a": "O Mistral Le Chat agora se chama Vibe. É o assistente de IA para consumidores da Mistral AI, disponível em chat.mistral.ai, e roda nos próprios modelos da Mistral, atualmente construído em torno do Mistral Medium 3.5. A Mistral é uma empresa francesa de IA que enfatiza a soberania de dados europeia e o desenvolvimento de modelos de pesos abertos.", "q": "O que é o Mistral Le Chat?"}, {"a": "O produto agora se chama Vibe. Ele tem um plano gratuito com mensagens, buscas na web e sessões de codificação limitadas, geração de imagens e $10/mês em créditos de API. O plano Pro custa $14,99/mês por mais mensagens, codificação o dia todo, geração de imagens e créditos de API incluídos.", "q": "O Le Chat é gratuito?"}, {"a": "A Mistral lança vários modelos como pesos abertos, incluindo Mistral Large, Medium 3.5, Small e Ministral, sob licenças abertas como Apache 2.0 ou uma licença MIT modificada, que os desenvolvedores podem baixar e executar por conta própria. O Vibe é o produto hospedado para consumidores da Mistral, construído sobre esses modelos.", "q": "Os modelos da Mistral são de código aberto?"}]$x$::jsonb
 WHERE slug = 'mistral-le-chat' AND lang = 'pt';

