UPDATE tools SET faq = $x$[{"q": "Was ist Claude Code?", "a": "Claude Code ist Anthropics offizieller Coding-Agent. Er liest Ihre Codebasis, schreibt Code, führt Befehle aus, behebt Fehler und erledigt Multi-File-Aufgaben eigenständig, wobei er im Terminal, in VS Code, JetBrains, einer Desktop-App oder im Web läuft."}, {"q": "Wie viel kostet Claude Code?", "a": "Claude Code ist in Claude Pro (ab 17 $/Monat bei jährlicher Abrechnung, 20 $/Monat bei monatlicher Abrechnung), Max (ab 100 $/Monat), Team Standard, Team Premium und Enterprise-Plänen enthalten. Bei diesen Plänen teilt sich Claude Code denselben Nutzungspool wie Ihre Claude-Chats; separate Pay-as-you-go-API-Nutzung ist ebenfalls über die Anthropic Console verfügbar."}, {"q": "Wie unterscheidet sich Claude Code von Cursor?", "a": "Claude Code läuft auch als VS Code- und JetBrains-Erweiterung, als Desktop-App und im Web, nicht nur im Terminal. Es ist für Entwickler konzipiert, die einen Agenten wollen, der über ihren gesamten Workflow hinweg Code liest, bearbeitet und ausführt, während Cursor eine vollständige IDE auf Basis von VS Code mit visueller Oberfläche ist."}, {"q": "Was kann Claude Code eigenständig tun?", "a": "Claude Code kann Dateien lesen und bearbeiten, Shell-Befehle ausführen, Tests ausführen, die Codebasis durchsuchen, Git verwalten und mehrstufige technische Aufgaben mit minimaler Anleitung durchgängig erledigen."}]$x$::jsonb
