UPDATE tools SET faq = $x$[{"q": "Що таке Claude Code?", "a": "Claude Code — це офіційний агент для програмування від Anthropic. Він читає ваш кодову базу, пише код, виконує команди, виправляє помилки та автономно завершує завдання з кількома файлами, працюючи з терміналу, VS Code, JetBrains, десктопного застосунку або вебу."}, {"q": "Скільки коштує Claude Code?", "a": "Claude Code включений у плани Claude Pro (від $17/місяць при річній оплаті, $20/місяць при помісячній), Max (від $100/місяць), Team Standard, Team Premium та Enterprise. У цих планах Claude Code використовує той самий пул ресурсів, що й ваші чати Claude; також доступне окреме використання API за моделлю оплати за фактичне використання через Anthropic Console."}, {"q": "Чим Claude Code відрізняється від Cursor?", "a": "Claude Code також працює як розширення для VS Code і JetBrains, як десктопний застосунок і у вебі, а не лише в терміналі. Він створений для розробників, які хочуть агента, що читає, редагує та виконує код у межах їхнього робочого процесу, тоді як Cursor — це повноцінна IDE, побудована на VS Code, з візуальним інтерфейсом."}, {"q": "Що Claude Code може робити автономно?", "a": "Claude Code може читати й редагувати файли, виконувати команди оболонки, запускати тести, шукати в кодовій базі, керувати git та завершувати багатоетапні інженерні завдання від початку до кінця з мінімальними підказками."}]$x$::jsonb
