UPDATE tools SET faq = $x$[{"q": "Was ist Cursor?", "a": "Cursor ist eine KI-native IDE auf Basis von VS Code. Sie verschafft der KI vollen Kontext über die Codebasis und kann als Agent mehrere Dateien bearbeiten, Terminalbefehle ausführen und Aufgaben end-to-end erledigen."}, {"q": "Wie viel kostet Cursor?", "a": "Neukunden melden sich über The X Subscription an, die fünf Stufen umfasst: Free, Plus für 8 $ pro Monat, Premium für 30 $ pro Monat, Super für 100 $ pro Monat und Ultra für 200 $ pro Monat. Diese Stufen teilen sich einen wöchentlichen Nutzungspool zwischen Grok und Cursor. Drittanbietermodelle von Anbietern wie Anthropic oder OpenAI sind in keiner Stufe enthalten und werden separat zu API-Listenpreisen aus vorausbezahltem Guthaben abgerechnet. Kunden, die bereits einen älteren Cursor-Plan hatten, können diesen behalten, aber der Wechsel zu The X Subscription ist optional und nicht rückgängig zu machen."}, {"q": "Ist Cursor sicher für meine Codebasis?", "a": "Die aktuelle Beschreibung geht nicht im Detail auf spezifische Datenschutz- oder Compliance-Funktionen ein, aber Cursor bietet eine Enterprise-Stufe mit individuellen Konditionen, in deren Rahmen typischerweise strengere Datenkontrollen und teamweite Governance geregelt würden."}, {"q": "Welche Modelle nutzt Cursor?", "a": "Das gebündelte Modell von Cursor ist Grok von xAI, das in jeder Stufe von The X Subscription enthalten ist und sich einen wöchentlichen Nutzungspool mit Cursor teilt. Cursor unterstützt zudem Drittanbietermodelle von Anbietern wie OpenAI, Anthropic und Google, die separat zum API-Preis aus vorausbezahltem Guthaben abgerechnet werden, und man kann das Modell pro Anfrage in den Einstellungen wechseln."}]$x$::jsonb
 WHERE slug = 'cursor' AND lang = 'de';

