UPDATE tools SET faq = $x$[{"q": "O que é o Cursor?", "a": "Cursor é um IDE nativo de IA baseado no VS Code. Ele dá à IA contexto completo da sua base de código e pode editar múltiplos arquivos, executar comandos de terminal e concluir tarefas de ponta a ponta como um agente."}, {"q": "Quanto custa o Cursor?", "a": "Novos clientes se inscrevem através da The X Subscription, que possui cinco níveis: Free, Plus por US$ 8 por mês, Premium por US$ 30 por mês, Super por US$ 100 por mês e Ultra por US$ 200 por mês. Esses níveis compartilham um pool de uso semanal entre Grok e Cursor. Modelos de terceiros de fornecedores como Anthropic ou OpenAI não estão incluídos em nenhum nível e são cobrados separadamente aos preços de tabela da API a partir de crédito pré-pago. Clientes que já tinham um plano antigo do Cursor podem mantê-lo, mas a mudança para a The X Subscription é opcional e não pode ser revertida."}, {"q": "É seguro usar o Cursor com minha base de código?", "a": "A descrição atual não detalha recursos específicos de privacidade ou conformidade, mas o Cursor oferece um nível Enterprise com termos personalizados, que é tipicamente onde controles de dados mais rígidos e governança em nível de equipe seriam tratados."}, {"q": "Quais modelos o Cursor usa?", "a": "O modelo empacotado do Cursor é o Grok, da xAI, incluído em todos os níveis da The X Subscription e compartilhando um pool de uso semanal com o Cursor. O Cursor também suporta modelos de terceiros de fornecedores como OpenAI, Anthropic e Google, cobrados separadamente ao preço da API a partir de crédito pré-pago, e você pode alternar entre modelos por solicitação nas configurações."}]$x$::jsonb
 WHERE slug = 'cursor' AND lang = 'pt';

