UPDATE tools SET faq = $x$[{"q": "What is Photoroom used for?", "a": "Photoroom is used to create product photos for online stores and marketplaces. It removes backgrounds, adds shadows, places products in AI-generated scenes, puts clothing on AI fashion models, makes short product videos and batch-edits whole catalogs."}, {"q": "Is Photoroom free?", "a": "There is a Free plan with limited features and lower credit and export limits, for personal, non-commercial use only and without API access. In the US, Pro costs $12.99 a month or $89.99 a year, Max $34.99 a month or $250.00 a year, and Ultra $99 a month or $990 a year. Pro and Max yearly plans include a 7-day free trial."}, {"q": "What are Photoroom AI credits?", "a": "AI credits pay for the heavier tools, such as the Video Generator, AI Fashion Models, AI Backgrounds Studio and Edit with AI. Pro includes 8,000 credits a month, Max 25,000 and Ultra 75,000. Core tools like the Background Remover and Retouch do not use credits on paid plans."}, {"q": "Does Photoroom have an API?", "a": "Yes. Photoroom offers a REST API and an MCP server for tools like Claude. Each paid plan includes a wallet of API and MCP credits worth the plan's price, and API usage does not count against your export allowance. The Free plan has no API access."}]$x$::jsonb
