UPDATE tools SET faq = $x$[{"q": "Freepik теперь называется Magnific?", "a": "Да. 28 апреля 2026 года Freepik провёл ребрендинг под именем Magnific, объединив свою стоковую библиотеку, инструменты ИИ-генерации и апскейлер Magnific под одним названием. freepik.com теперь перенаправляет на magnific.com."}, {"q": "Magnific (Freepik) бесплатен?", "a": "На текущей странице цен нет бесплатного плана; индивидуальные платные планы — это Premium, Premium+ и Pro Starter, а для крупных организаций доступны отдельные планы Teams. Цены на сайте показываются в местной валюте и варьируются по регионам; внутриприложенческая подписка в американском App Store указывает Premium за $26,00 в месяц (или $234,99 в год) и Premium+ за $55,00 в месяц (или $494,99 в год)."}, {"q": "Какие ИИ-модели включает Magnific?", "a": "Magnific предлагает множество ведущих сторонних моделей, включая Kling, Seedance, Google Veo, Gemini Omni, MiniMax, Nano Banana, FLUX, Recraft, Ideogram и Grok, а также собственную модель изображений Magnific One (включена во все платные планы) и инструменты музыки и звука от Google Lyria и ElevenLabs."}, {"q": "Что означает «неограниченно» в Magnific?", "a": "Большинство платных планов включают неограниченную генерацию на отдельных моделях изображений в течение части года или всего года, хотя конкретный набор моделей с безлимитом может различаться в зависимости от плана. Инструменты для видео, аудио и редактирования по-прежнему расходуют кредиты, а скорость может быть ограничена в периоды высокой нагрузки."}]$x$::jsonb
