UPDATE tools SET faq = $x$[{"q": "A Freepik agora se chama Magnific?", "a": "Sim. Em 28 de abril de 2026, a Freepik mudou de marca para Magnific, unindo sua biblioteca de banco de imagens, ferramentas de geração por IA e o upscaler Magnific sob um único nome. O site freepik.com agora redireciona para magnific.com."}, {"q": "O Magnific (Freepik) é gratuito?", "a": "A página de preços atual não lista um plano gratuito; os planos pagos individuais são Premium, Premium+ e Pro Starter, com planos Teams separados para organizações maiores. Os preços no site são exibidos na moeda local e variam por região; os preços de assinatura no aplicativo na App Store dos EUA listam o Premium a $26,00 por mês (ou $234,99 por ano) e o Premium+ a $55,00 por mês (ou $494,99 por ano)."}, {"q": "Quais modelos de IA o Magnific inclui?", "a": "O Magnific oferece diversos modelos líderes de terceiros, incluindo Kling, Seedance, Google Veo, Gemini Omni, MiniMax, Nano Banana, FLUX, Recraft, Ideogram e Grok, além de seu próprio modelo de imagem Magnific One (incluído em todos os planos pagos) e ferramentas de música e som do Google Lyria e ElevenLabs."}, {"q": "O que significa ilimitado no Magnific?", "a": "A maioria dos planos pagos inclui geração ilimitada em modelos de imagem selecionados por parte ou a totalidade do ano, embora os modelos específicos considerados ilimitados possam variar conforme o plano. Ferramentas de vídeo, áudio e edição ainda consomem créditos, e a velocidade pode ser limitada em períodos de alta demanda."}]$x$::jsonb
 WHERE slug = 'freepik' AND lang = 'pt';
